  for(const id of ['large-x','large-z','shell-height','shell-pillars','shell-lateral','shell-tip','shell-diameter','shell-beam-width','shell-beam-height','shell-ocean','shell-sea-level','large-h','large-relief'])q('#'+id).addEventListener('input',sizeNote);sizeNote();
  const formConfig=()=>{const features=Object.fromEntries(['city','dungeon','labyrinth','arena','trees'].map(k=>[k,q('#large-'+k).checked])),pct=id=>Number(q('#ain-'+id).value)/100;return {...{width:Number(q('#large-x').value),depth:Number(q('#large-z').value),height:Number(q('#large-h').value),name:q('#large-name').value,seed:q('#large-seed').value,topology:q('#large-topology').value,biome:q('#large-biome').value,islandCount:Number(q('#large-islands').value),mazeLevels:Number(q('#large-levels').value),relief:Number(q('#large-relief').value),caves:q('#large-caves').checked,bridges:q('#large-bridges').checked,features,heightmap,biomeMap,reference,shell:{enabled:true,margin:1000,wallHeight:Number(q('#shell-height').value),pillarCount:Number(q('#shell-pillars').value),lateralLength:Number(q('#shell-lateral').value),tipLength:Number(q('#shell-tip').value),pillarRadius:Number(q('#shell-diameter').value)/2,beamWidth:Number(q('#shell-beam-width').value),beamHeight:Number(q('#shell-beam-height').value),oceanEnabled:q('#shell-ocean').checked,seaLevel:q('#shell-sea-level').value===''?null:Number(q('#shell-sea-level').value)}},floor:Number(q('#ain-floor').value),aincrad:{city:pct('city'),villages:Number(q('#ain-villages').value),forest:pct('forest'),mountains:pct('mountains'),water:pct('water'),pois:pct('pois')}};};
  let overviewConfig=null,miniRenderer=null,miniDirty=true,mini=null,previewing=false,appliedScale=1,previewTimer=null;const overview=q('#large-overview');document.querySelector('#dialog').addEventListener('close',()=>{clearTimeout(previewTimer);try{miniRenderer?.dispose();}catch{}miniRenderer=null;},{once:true});
  const pickMini=point=>{if(!mini||!overviewConfig)return;if(previewing){q('#floor-miniature-info').textContent='Esta é uma pré-visualização. Crie o mundo para abrir janelas de edição.';return;}const g=floorGeometry(overviewConfig),size=Number(q('#window-size').value),wx=mini.origin[0]+(point[0]+.5)*mini.step,wz=mini.origin[1]+(point[2]+.5)*mini.step;q('#window-x').value=Math.max(g.minX,Math.min(g.maxX-size,Math.floor((wx-size/2)/16)*16));q('#window-z').value=Math.max(g.minZ,Math.min(g.maxZ-size,Math.floor((wz-size/2)/16)*16));paint();q('#floor-miniature-info').textContent=`Janela posicionada em X ${q('#window-x').value}, Z ${q('#window-z').value}. Clique em Abrir janela para editar esse ponto.`;};
  const miniature=(l,g)=>{if(!miniDirty)return;miniDirty=false;try{mini=floorMiniature(l,g);miniRenderer=miniRenderer||new Renderer(q('#floor-miniature'),pickMini);miniRenderer.setWorld(mini.world);miniRenderer.reset();miniRenderer.distance*=.6;miniRenderer.target=[mini.world.w/2,mini.world.h*.2,mini.world.d/2];miniRenderer.draw();const places=l.layout?.places||[];q('#floor-miniature-info').textContent=(previewing?'Pré-visualização (ainda não criado)':'Andar completo gerado')+` · terreno ${l.config.width} × ${l.config.depth} blocos · 1 cubo ≈ ${mini.step.toFixed(1)} blocos.`+(places.length?' Locais: '+places.slice(0,7).map(p=>`${p.name} (X ${p.x}, Z ${p.z})`).join(' · ')+(places.length>7?` · e mais ${places.length-7}`:'')+'. Clique na miniatura para escolher a janela.':'');}catch(e){q('#floor-miniature-info').textContent='Miniatura 3D indisponível: '+e.message;}};
